    let phonemes2 = word2.phonemes()

    return phonemes1 == phonemes2
}

func replaceHomophones(in passage: String) -> String {
    var correctedPassage = passage

    // Replace "their", "there", and "they're"
    correctedPassage = correctedPassage.replacingOccurrences(of: "their", with: "there")
    correctedPassage = correctedPassage.replacingOccurrences(of: "there", with: "they're")
