Here's a simple MATLAB code that identifies the tense of a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Check for common tense markers
    for i = 1:length(words)
        if strcmpi(words{i}, 'will') || strcmpi(words{i}, 'would') || strcmpi(words{i}, 'have') || strcmpi(words{i}, 'had') || strcmpi(words{i}, 'is') || strcmpi(words{i}, 'are') || strcmpi(words{i}, 'be') || strcmpi(words{i}, 'being') || strcmpi(words{i}, 'was') || strcmpi(words{i}, 'were')
            tense = words{i};
            break;
        end
    end
end

