  if (isValidIPv6(sourceIP) && isValidIPv6(destinationIP)) {
    // If both source and destination IP addresses are IPv6, check for UDP or TCP
    if (port === 0 || port > 65535) {
      return 'UDP';
    } else {
      return 'TCP';
    }
  } else if (isValidIPv4(sourceIP) && isValidIPv4(destinationIP)) {
    // If both source and destination IP addresses are IPv4, check for HTTP
    if (port === 80) {
      return 'HTTP';
    } else {
      return 'TCP';
    }
  } else {
    // If neither source nor destination IP address is valid, return an error message
    return 'Invalid IP address';
  }
}

function isValidIPv6(ipAddress) {
  // Regular expression pattern to validate IPv6 addresses
  const ipv6Regex = /^([0-9A-Fa-f]{1,4}:){7}([0-9A-Fa-f]{1,4})$/;
  return ipv6Regex.test(ipAddress);
}

function isValidIPv4(ipAddress) {
  // Regular expression pattern to validate IPv4 addresses
  const ipv4Regex = /^(\d{1,3}\.){3}(\d{1,3})$/;
  return ipv4Regex.test(ipAddress);
}
```

