     */
    public function up()
    {
        Schema::create('users', function (Blueprint $table) {
            $table->id();
            $table->string('name');
            $table->email('email');
            $table->password('password');
            $table->string('phone');
            $table->text('address');
            $table->timestamps();

            // Relationships
            $table->hasMany('cars');
            $table->hasMany('pets');
            $table->hasOne('house');
        });
    }

    /**
     * Reverse the migrations.
     *
     * @return void
     */
    public function down()
    {
        Schema::dropIfExists('users');
    }
}
```

This migration creates a `users` table with the following columns:

* `id` (integer, primary key)
* `name` (string)
* `email` (string)
* `password` (string)
* `phone` (string)
* `address` (text)
* `created_at` (timestamp)
