Here's an example of how you can create a React component using Hooks to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const convertTemperature = () => {
    if (unit === 'celsius') {
      return `${temperature}°C is equal to ${(temperature * 1.8) + 32}°F`;
    } else if (unit === 'fahrenheit') {
      return `${temperature}°F is equal to ${(temperature - 32) / 1.8}°C`;
    }
  };

  return (
    <div>
      <label htmlFor="temperature">Enter the temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={handleInputChange} />
      <label htmlFor="unit">Select the unit:</label>
      <select id="unit" value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
      <p>{convertTemperature()}</p>
    </div>
  );
};

export default TemperatureConverter;
```

